package uz.uzkey.keyboard.core

import org.json.JSONObject

/** A key-click sound pack from shared/sounds/packs.json (generated by tools/build_sounds.py). */
data class SoundPack(
    val id: String,
    /** Number of key sounds, `key1.wav` … `keyN.wav`. */
    val keyVariants: Int,
    /** True when each key always plays the same variant (musical packs); otherwise a variant is picked at random. */
    val variantByKey: Boolean,
)

object SoundPacks {
    /** The platform's own click; it has no files. */
    const val SYSTEM = "system"
    const val DEFAULT = "mechanical"

    fun parse(json: String): List<SoundPack> {
        val packs = JSONObject(json).getJSONArray("packs")
        return (0 until packs.length()).map { index ->
            val pack = packs.getJSONObject(index)
            SoundPack(
                id = pack.getString("id"),
                keyVariants = pack.getInt("keys").coerceAtLeast(1),
                variantByKey = pack.optString("variation") == "by_key",
            )
        }
    }

    /** The key sound variant a key plays: musical packs map each key to a fixed note, others vary at random. */
    fun keyVariant(pack: SoundPack, label: String?, random: () -> Int): Int {
        if (pack.keyVariants == 1) return 0
        if (pack.variantByKey && !label.isNullOrEmpty()) {
            val code = label.lowercase()[0].code
            return Math.floorMod(code, pack.keyVariants)
        }
        return Math.floorMod(random(), pack.keyVariants)
    }
}
